"use server";

import { createServerClient } from "@supabase/ssr";
import { cookies } from "next/headers";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

async function getSupabase() {
    const cookieStore = await cookies();
    return createServerClient(
        process.env.NEXT_PUBLIC_SUPABASE_URL!,
        process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
        {
            cookies: {
                getAll() {
                    return cookieStore.getAll();
                },
                setAll(cookiesToSet) {
                    try {
                        cookiesToSet.forEach(({ name, value, options }) =>
                            cookieStore.set(name, value, options)
                        );
                    } catch {
                        // Server Component
                    }
                },
            },
        }
    );
}

// Helper to check if current user is admin
async function checkAdmin() {
    const supabase = await getSupabase();
    console.log("checkAdmin: fetching current user...");
    const { data: { user } } = await supabase.auth.getUser();
    if (!user) {
        console.log("checkAdmin: No user session found");
        throw new Error("Unauthorized: No session");
    }
    console.log("checkAdmin: User found", user.id);

    const { data: profile } = await supabase
        .from("profiles")
        .select("role")
        .eq("id", user.id)
        .single();

    console.log("checkAdmin: User role is", profile?.role);

    if (!profile || (profile.role !== "admin" && profile.role !== "super_admin")) {
        console.log("checkAdmin: Access denied - insufficient permissions");
        throw new Error("Unauthorized: Insufficient permissions");
    }
    return { supabase, user };
}

export async function toggleBanUser(userId: string, currentStatus: boolean) {
    console.log("toggleBanUser triggered:", { userId, currentStatus });
    try {
        const { supabase } = await checkAdmin();
        console.log("Admin check passed");

        // Prevent banning yourself
        const { data: { user } } = await supabase.auth.getUser();
        if (user!.id === userId) {
            console.log("Aborting: Cannot ban self");
            throw new Error("You cannot ban yourself.");
        }

        console.log("Attempting database update...");
        const { error } = await supabase
            .from("profiles")
            .update({ is_banned: !currentStatus })
            .eq("id", userId);

        if (error) {
            console.error("Database update error:", error);
            throw error;
        }

        console.log("Database update successful. Revalidating path...");
        revalidatePath("/admin/users");
        return { success: true };
    } catch (error: any) {
        console.error("toggleBanUser error caught:", error.message);
        return { success: false, error: error.message };
    }
}

export async function updateUserRole(userId: string, newRole: "user" | "admin" | "super_admin") {
    try {
        const { supabase } = await checkAdmin();

        // Prevent changing your own role (optional, but good safety)
        const { data: { user } } = await supabase.auth.getUser();
        if (user!.id === userId) {
            // throw new Error("You cannot change your own role."); 
            // Allowing it for now but be careful
        }

        const { error } = await supabase
            .from("profiles")
            .update({ role: newRole })
            .eq("id", userId);

        if (error) throw error;

        revalidatePath("/admin/users");
        return { success: true };
    } catch (error: any) {
        return { success: false, error: error.message };
    }
}

export async function deleteUser(userId: string) {
    try {
        const supabase = await createServerClient(
            process.env.NEXT_PUBLIC_SUPABASE_URL!,
            process.env.SUPABASE_SERVICE_KEY!,
            {
                cookies: {
                    getAll() { return [] },
                    setAll() { }
                }
            }
        );

        // Prevent deleting yourself (extra safety, though client checks too)
        // Would need to check auth.uid() from cookies but we are using service role here.
        // So we skip that check or pass current user ID as arg if critical.

        const { error } = await supabase.auth.admin.deleteUser(userId);

        if (error) throw error;

        revalidatePath("/admin/users");
        return { success: true };
    } catch (error: any) {
        console.error("Delete Error:", error);
        return { success: false, error: error.message };
    }
}
